// ─── Shared locked TS↔Cairo test vectors ───
// Real Ed25519 signatures (signer = seed 0..31) over the base64 message form
// SolAccount verifies: the 44-char standard base64 of LOCKED_HASH's 32 big-endian
// bytes, both WITHOUT a label and WITH a readable label (label + "\n" + base64). Used
// by garaga.test.ts (the felt-bundle encoding) and signer.test.ts (the full signRaw
// path) so the off-chain → on-chain encoding is pinned from a single source. The felt
// bundles those tests assert, and the matching sol_account Cairo vectors (sig1 /
// sig1_labeled), are regenerated by scripts/gen_contract_vectors.mjs, which re-signs
// the seed 0..31 over messages built from the LOCKED_HASH / LOCKED_LABEL anchors below
// (cross-checking its pubkey against LOCKED_PUBKEY); it never reads the signature bytes.
// LOCKED_SIG64 and LOCKED_SIG64_LABELED are the resulting signatures those two tests
// assert against. Do not edit without re-verifying against Cairo (re-run `snforge test`).

import { createPrivateKey, sign as ed25519Sign } from "node:crypto";
import type { SolanaSigner } from "./signer";

/** The felt operation hash the wallet signs. */
export const LOCKED_HASH = 0x1a2b3c4d5e6f70819293a4b5c6d7e8f90a1b2c3d4e5f60718293a4b5c6d7e8n;
/** The "0x"+hex felt form handed to signRaw (starknet.js passes the unpadded felt). */
export const LOCKED_HASH_HEX = "0x" + LOCKED_HASH.toString(16);
/** The 44-char standard base64 of LOCKED_HASH's 32 big-endian bytes (one '=' pad). */
export const LOCKED_B64 = "ABorPE1eb3CBkpOktcbX6PkKGyw9Tl9gcYKTpLXG1+g=";
/** A readable label pinned for the labeled-path vector (40 UTF-8 bytes -> 2 SHA-512
 *  blocks). Proves the label + "\n" + base64 layout end to end, TS<->Cairo. */
export const LOCKED_LABEL = "anystark: transfer 25 USDC to alice.strk";

// prettier-ignore
export const LOCKED_PUBKEY = Uint8Array.from([3, 161, 7, 191, 243, 206, 16, 190, 29, 112, 221, 24, 231, 75, 192, 153, 103, 228, 214, 48, 155, 165, 13, 95, 29, 220, 134, 100, 18, 85, 49, 184]);
// Ed25519 signature (seed 0..31) over the NO-LABEL base64 message (44 bytes).
// prettier-ignore
export const LOCKED_SIG64 = Uint8Array.from([82, 239, 131, 165, 177, 65, 246, 172, 155, 27, 11, 43, 235, 40, 231, 137, 61, 219, 46, 45, 17, 51, 146, 206, 209, 238, 27, 27, 124, 112, 195, 141, 53, 164, 168, 132, 139, 19, 221, 134, 62, 168, 129, 215, 143, 189, 53, 227, 203, 231, 201, 209, 1, 63, 131, 10, 206, 164, 143, 195, 13, 78, 180, 2]);
// Ed25519 signature (seed 0..31) over the LABELED message (LOCKED_LABEL + "\n" + base64, 85 bytes).
// prettier-ignore
export const LOCKED_SIG64_LABELED = Uint8Array.from([211, 204, 150, 167, 116, 107, 136, 61, 125, 149, 201, 37, 51, 107, 119, 50, 192, 115, 38, 181, 168, 163, 202, 213, 34, 62, 192, 108, 173, 178, 73, 207, 167, 159, 118, 244, 121, 142, 141, 122, 211, 26, 211, 49, 24, 79, 67, 244, 237, 136, 172, 203, 176, 88, 185, 39, 147, 92, 23, 86, 150, 234, 146, 8]);

/** PKCS8 DER prefix that wraps a raw 32-byte Ed25519 seed into an import-able key. */
const ED25519_PKCS8_PREFIX = "302e020100300506032b657004220420";

/**
 * The locked test wallet itself: seed bytes 0..31, the private key behind
 * LOCKED_PUBKEY, signing for real via node:crypto. For tests that must produce
 * VALID Ed25519 signatures over messages whose bytes the test doesn't precompute
 * (e.g. SNIP-12 typed-data hashes assembled inside the code under test).
 */
export function lockedEd25519Signer(): SolanaSigner {
  const seed = Uint8Array.from({ length: 32 }, (_, i) => i);
  const key = createPrivateKey({
    key: Buffer.concat([Buffer.from(ED25519_PKCS8_PREFIX, "hex"), Buffer.from(seed)]),
    format: "der",
    type: "pkcs8",
  });
  return {
    pubkey: LOCKED_PUBKEY,
    signBytes: async (message) => new Uint8Array(ed25519Sign(null, message, key)),
  };
}
